mapper.select:
SELECT PRCR.COLLECTION_RULE_ID, PRCR.COLLECTION_DAYS, PRCR.DESCRIPTION, PRCR.ENABLED_FLAG, PRCR.LAST_COLLECTION_DATE, HDT.DESCRIPTION DOCUMENT_TYPE_DESC, con.CONTRACT_NUMBER as contract_id_n, CON.*
FROM PLM_RENT_COLLECTION_RULE PRCR JOIN ( SELECT CC.CONTRACT_NUMBER, CC.CONTRACT_NAME, PP.APPROVAL_NUMBER, CC.CONTRACT_ID, CC.DOCUMENT_TYPE, CC.BUSINESS_TYPE, CC.TENANT_ID AS BP_ID, HBM.BP_NAME, 'CON_CONTRACT' AS CONTRACT_DOC_CATEGORY, nvl( ( SELECT MAX(CCC.TIMES) FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID GROUP BY CCC.CONTRACT_ID ),0) AS ALL_TIMES, ( SELECT COUNT(1) FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID AND CCC.CF_ITEM = 9 ) AS OVERDUE_TIMES, nvl( ( SELECT MAX(CCC.FINE_DAYS) FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID AND CCC.CF_ITEM = 1 AND CCC.OVERDUE_STATUS = 'Y' GROUP BY CCC.CONTRACT_ID ),0) AS OVERDUE_DAYS, nvl( ( SELECT SUM(CCC.DUE_AMOUNT-CCC.RECEIVED_AMOUNT) FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID AND CCC.CF_ITEM = 1 AND CCC.OVERDUE_STATUS = 'Y' AND CCC.WRITE_OFF_FLAG != 'FULL' GROUP BY CCC.CONTRACT_ID),0) AS OVERDUE_AMOUNT, nvl( ( SELECT SUM(CCC.DUE_AMOUNT-CCC.RECEIVED_AMOUNT) FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID AND CCC.CF_ITEM = 9 GROUP BY CCC.CONTRACT_ID),0) AS OVERDUE_PENALTY, ( SELECT CASE WHEN COUNT(1) > 0 THEN 'N' ELSE 'Y' END FROM CON_CONTRACT_CASHFLOW CCC WHERE CCC.CONTRACT_ID = CC.CONTRACT_ID AND CCC.CF_ITEM = 1 AND CCC.WRITE_OFF_FLAG != 'FULL' ) AS IS_SETTLE FROM CON_CONTRACT CC JOIN PRJ_PROJECT PP ON PP.PROJECT_ID=CC.PROJECT_ID LEFT JOIN HLS_BP_MASTER HBM ON CC.TENANT_ID = HBM.BP_ID WHERE CC.DATA_CLASS = 'NORMAL'
UNION ALL SELECT FCT.CONTRACT_NUMBER, FCT.CONTRACT_NAME, FCT.APPROVAL_NUMBER, FCT.CONTRACT_ID, FCT.DOCUMENT_TYPE, FCT.BUSINESS_TYPE, HBM.BP_ID, HBM.BP_NAME, 'FCT_CONTRACT' AS CONTRACT_DOC_CATEGORY, nvl( ( SELECT MAX(FQC.TIMES) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID GROUP BY FCT.CONTRACT_ID ), 0 ) AS ALL_TIMES, ( SELECT COUNT(1) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID AND FQC.CF_ITEM = 45 ) AS OVERDUE_TIMES, nvl( ( SELECT MAX(FQC.FINE_DAYS) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID AND FQC.CF_ITEM IN(54, 55, 57, 51) AND FQC.OVERDUE_STATUS = 'Y' GROUP BY FQC.CONTRACT_ID ), 0 ) AS OVERDUE_DAYS, nvl( ( SELECT SUM(FQC.DUE_AMOUNT-nvl(FQC.RECEIVED_AMOUNT,0)) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID AND FQC.CF_ITEM IN (54, 55, 57, 59) AND FQC.WRITE_OFF_FLAG != 'FULL' AND FQC.OVERDUE_STATUS = 'Y' GROUP BY FQC.CONTRACT_ID ), 0 ) AS OVERDUE_AMOUNT, nvl( ( SELECT SUM(FQC.DUE_AMOUNT-nvl(FQC.RECEIVED_AMOUNT,0)) FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID AND FQC.CF_ITEM = 45 GROUP BY FQC.CONTRACT_ID ), 0 ) AS OVERDUE_PENALTY, ( SELECT CASE WHEN COUNT(1) > 0 THEN 'N' ELSE 'Y' END FROM FCT_QUOTATION_CASHFLOW FQC WHERE FQC.CONTRACT_ID = FCT.CONTRACT_ID AND FQC.CF_ITEM IN (54, 55, 57, 51) AND FQC.WRITE_OFF_FLAG != 'FULL' ) AS IS_SETTLE FROM FCT_CONTRACT FCT, FCT_PROJECT_BP FPB, HLS_BP_MASTER HBM WHERE FCT.DATA_CLASS = 'NORMAL' AND FCT.PROJECT_ID = FPB.PROJECT_ID AND FPB.BP_ID = HBM.BP_ID AND FPB.CREDIT_GRANTOR_PARTY='Y'
) CON ON CON.CONTRACT_ID=PRCR.CONTRACT_ID AND CON.CONTRACT_DOC_CATEGORY=PRCR.CONTRACT_DOC_CATEGORY LEFT JOIN HLS_DOCUMENT_TYPE HDT ON HDT.DOCUMENT_CATEGORY=CON.CONTRACT_DOC_CATEGORY AND HDT.DOCUMENT_TYPE=CON.DOCUMENT_TYPE AND HDT.BUSINESS_TYPE=CON.BUSINESS_TYPE WHERE 1=1
AND (CON.CONTRACT_NUMBER LIKE CONCAT(CONCAT('%',#{collectionRuleQuery}),'%') OR CON.BP_NAME LIKE CONCAT(CONCAT('%',#{collectionRuleQuery}),'%') OR CON.APPROVAL_NUMBER LIKE CONCAT(CONCAT('%',#{collectionRuleQuery}),'%') )
AND PRCR.COLLECTION_RULE_ID=#{collectionRuleId}

SELECT
    COUNT(1)
  FROM
      PLM_RENT_COLLECTION_RULE PRCR
  WHERE
       PRCR.CONTRACT_ID=#{contractId}
    AND
       PRCR.CONTRACT_DOC_CATEGORY=#{contractDocCategory}

     AND  PRCR.COLLECTION_RULE_ID!=#{collectionRuleId}
